/* Task-wide access to the workflow, with approval restricted to the named reviewer. */
(()=>{'use strict';if(!document.body.classList.contains('shared-app'))return;
const q=s=>document.querySelector(s);
const previousAction=action;action=async function(t,kind,...args){if(kind==='approve'&&!reviewer(t)){message('تأیید نهایی این کار فقط در اختیار تأییدکنندهٔ مشخص‌شده است.');return}return previousAction(t,kind,...args)};
async function workflow(id){await detail(id)}
function decorate(){if(window.SAMANDIS_PERSONAL_MODE)return;document.querySelectorAll('#sharedContent .clarity-table tbody tr,#sharedContent .desk-task-card').forEach(row=>{const title=row.querySelector('[data-task],[data-shared-card]'),id=title?.dataset.task||title?.dataset.sharedCard,t=tasks.find(x=>x.id===id);if(!t)return;row.dataset.workflowTask=id;row.classList.add('workflow-clickable');const target=row.matches('tr')?row.children[1]:row.querySelector('.card-bottom');if(target&&!target.querySelector('.task-reviewer-caption')){const text=document.createElement('small');text.className='task-reviewer-caption';text.textContent=t.reviewer_id?'تأییدکننده: '+person(t.reviewer_id):'بدون نیاز به تأیید';target.append(text)}if(!row.querySelector('.task-workflow-source')){const b=document.createElement('button');b.type='button';b.className='task-workflow-source task-overflow-source';b.textContent='مشاهده روند ارجاع و سوابق';b.onclick=e=>{e.stopPropagation();workflow(id)};(row.matches('tr')?row.lastElementChild:row).append(b)}title.onclick=e=>{e.stopPropagation();workflow(id)}});window.SamandisCollectTaskActions?.()}
document.addEventListener('click',e=>{if(e.defaultPrevented||e.target.closest('button,a,input,select,textarea,label,summary,[role=button],[data-tooltip]'))return;const row=e.target.closest('[data-workflow-task]');if(row&&!window.getSelection()?.toString())workflow(row.dataset.workflowTask)});
const previousDetail=detail;detail=async function(id,...args){await previousDetail(id,...args);const root=q('#sharedDetail');if(selectedTask!==id||!q('#sharedDialog')?.open)return;const history=[...root.querySelectorAll('details')].find(d=>/همه سوابق/.test(d.querySelector('summary')?.textContent||''));if(!history)return;try{const rows=await checked(db.from('sm_events').select('*').eq('task_id',id).order('created_at'));if(selectedTask!==id||!history.isConnected)return;const titles={created:'تعریف و ثبت کار',assign:'ارجاع و تعیین عوامل اجرا',submit:'اتمام و ارسال برای بررسی',approve:'تأیید نهایی',correct:'درخواست اصلاح',reopen:'بازگشایی کار',edit:'ویرایش مشخصات کار',report:'ثبت گزارش و بازخورد',file:'ثبت نسخهٔ فایل',request:'درخواست تغییر ارجاع'};history.innerHTML='<summary>روند ارجاع و سوابق ('+fa(rows.length)+')</summary><ol class="task-workflow-timeline">'+rows.map(e=>{const after=e.payload?.after,assigned=e.kind==='assign'&&after;return '<li><strong>'+esc(e.kind==='submit'&&after?.status==='done'?'اتمام کار':titles[e.kind]||'به‌روزرسانی کار')+'</strong><span>'+esc(person(e.actor_id))+' · '+esc(date(e.created_at))+'</span>'+(assigned?'<p>مسئول اجرا: '+esc(person(after.owner_id))+(after.collaborators?.length?' · همکاران: '+after.collaborators.map(person).map(esc).join('، '):'')+'</p>':'')+'</li>'}).join('')+'</ol>'}catch(e){message(failure(e))}};
const previousRender=render;render=function(...args){const r=previousRender(...args);decorate();return r};const previousTasks=renderTasks;renderTasks=function(...args){const r=previousTasks(...args);decorate();return r};decorate();
})();
